/**
 * The complete KEY Role Taxonomy — all 84 intelligence archetypes.
 * Use the helper functions below for filtered access.
 */
export const KEY_ROLE_TAXONOMY: KeyRoleBrain[] = [
  ...STRATEGY_ROLES,
  ...OPERATIONS_ROLES,
  ...FINANCE_ROLES,
  ...SALES_ROLES,
  ...MARKETING_ROLES,
  ...CUSTOMER_SUCCESS_ROLES,
  ...PRODUCT_ROLES,
  ...PEOPLE_ROLES,
  ...LEGAL_RISK_ROLES,
  ...ANALYTICS_ROLES,
  ...TECHNOLOGY_ROLES,
  ...ADMIN_ROLES,
];

/** Total count of roles in the taxonomy. */
export const ROLE_COUNT = KEY_ROLE_TAXONOMY.length;

/** Count of roles per business function. */
export const ROLE_COUNT_BY_FUNCTION: Record<BusinessFunction, number> = {
  strategy: STRATEGY_ROLES.length,
  operations: OPERATIONS_ROLES.length,
  finance: FINANCE_ROLES.length,
  sales: SALES_ROLES.length,
  marketing: MARKETING_ROLES.length,
  customer_success: CUSTOMER_SUCCESS_ROLES.length,
  product: PRODUCT_ROLES.length,
  people: PEOPLE_ROLES.length,
  legal_risk: LEGAL_RISK_ROLES.length,
  analytics: ANALYTICS_ROLES.length,
  technology: TECHNOLOGY_ROLES.length,
  admin: ADMIN_ROLES.length,
};

/** Count of roles per worker tier. */
export const ROLE_COUNT_BY_TIER: Record<WorkerTier, number> =
  ALL_WORKER_TIERS.reduce(
    (acc, tier) => {
      acc[tier] = KEY_ROLE_TAXONOMY.filter((r) => r.tier === tier).length;
      return acc;
    },
    {} as Record<WorkerTier, number>,
  );

// ═══════════════════════════════════════════════════════════════════════════
// HELPER FUNCTIONS
// ═══════════════════════════════════════════════════════════════════════════

/**
 * Get all roles for a given business function.
 * @param fn — the business function to filter by
 * @returns array of matching KeyRoleBrain objects
 * @example
 * ```ts
 * const strategyRoles = getRolesByFunction('strategy');
 * // => [Founder, CEO, CSO, ...]
 * ```
 */
export function getRolesByFunction(fn: BusinessFunction): KeyRoleBrain[] {
  return KEY_ROLE_TAXONOMY.filter((r) => r.functionArea === fn);
}

/**
 * Get all roles for a given worker tier.
 * @param tier — the worker tier to filter by
 * @returns array of matching KeyRoleBrain objects
 * @example
 * ```ts
 * const execRoles = getRolesByTier('executive');
 * // => [CEO, CFO, CMO, CTO, CHRO, ...]
 * ```
 */
export function getRolesByTier(tier: WorkerTier): KeyRoleBrain[] {
  return KEY_ROLE_TAXONOMY.filter((r) => r.tier === tier);
}

/**
 * Get roles filtered by both business function and worker tier.
 * Typically returns 0 or 1 role since each function/tier combo is unique.
 * @param fn — the business function
 * @param tier — the worker tier
 * @returns array of matching KeyRoleBrain objects
 * @example
 * ```ts
 * const cfo = getRolesByFunctionAndTier('finance', 'founder_partner');
 * // => [CFO]
 * ```
 */
export function getRolesByFunctionAndTier(
  fn: BusinessFunction,
  tier: WorkerTier,
): KeyRoleBrain[] {
  return KEY_ROLE_TAXONOMY.filter(
    (r) => r.functionArea === fn && r.tier === tier,
  );
}

/**
 * Get a single role by its unique identifier.
 * @param id — the role ID (e.g. `'strategy-ceo'`)
 * @returns the matching KeyRoleBrain, or undefined if not found
 * @example
 * ```ts
 * const role = getRoleById('finance-cfo');
 * // => { id: 'finance-cfo', name: 'Chief Financial Officer', ... }
 * ```
 */
export function getRoleById(id: string): KeyRoleBrain | undefined {
  return KEY_ROLE_TAXONOMY.find((r) => r.id === id);
}

/**
 * Search roles by name or keyword (case-insensitive).
 * @param keyword — the search term
 * @returns array of matching KeyRoleBrain objects
 * @example
 * ```ts
 * const chiefs = searchRoles('Chief');
 * // => [CFO, CMO, CTO, CHRO, ...]
 * ```
 */
export function searchRoles(keyword: string): KeyRoleBrain[] {
  const lower = keyword.toLowerCase();
  return KEY_ROLE_TAXONOMY.filter(
    (r) =>
      r.name.toLowerCase().includes(lower) ||
      r.mission.toLowerCase().includes(lower) ||
      r.id.toLowerCase().includes(lower),
  );
}

/**
 * Get all unique frameworks used across the taxonomy.
 * @returns alphabetically-sorted array of unique framework names
 */
export function getAllFrameworks(): string[] {
  const set = new Set<string>();
  for (const role of KEY_ROLE_TAXONOMY) {
    for (const fw of role.frameworks) {
      set.add(fw);
    }
  }
  return Array.from(set).sort();
}

/**
 * Get all unique thinking styles used across the taxonomy.
 * @returns alphabetically-sorted array of unique thinking styles
 */
export function getAllThinkingStyles(): string[] {
  return Array.from(
    new Set(KEY_ROLE_TAXONOMY.map((r) => r.thinkingStyle)),
  ).sort();
}

/**
 * Get all unique communication styles used across the taxonomy.
 * @returns alphabetically-sorted array of unique communication styles
 */
export function getAllCommunicationStyles(): string[] {
  return Array.from(
    new Set(KEY_ROLE_TAXONOMY.map((r) => r.communicationStyle)),
  ).sort();
}
